example:
type Event = { at: Int, kind: String }

agent Feed {
    key id: String
    store events: Map[String, Event]

    on call recent() -> Effect[List[Event]] {
        events.values.takeWhile((e) => e.at > 100).collect()    // ✗ a `Map` scan has no declared order
    }
}

agent Feed {
    key id: String
    store events: Map[String, Event]

    on call recent() -> Effect[List[Event]] {
        events.values.sortBy((e) => e.at).takeWhile((e) => e.at > 100).collect()    // ✓ ordered by `at`
    }
}
